<?php
namespace Tests\Feature;
use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class StockLedgerTest extends TestCase {use RefreshDatabase;public function test_adjustments_and_transfers_are_atomic_and_prevent_negative_stock():void{$this->seed();$token=$this->postJson('/api/v1/auth/login',['email'=>'admin@stockflow.local','password'=>'StockFlow@2026!'])->json('token');$h=['Authorization'=>'Bearer '.$token];$product=$this->postJson('/api/v1/products',['sku'=>'STOCK-1','name'=>'Stock Test','costPrice'=>10,'sellingPrice'=>15],$h)->assertCreated()->json('_id');$warehouses=$this->getJson('/api/v1/warehouses',$h)->assertOk()->json();$from=$warehouses[0]['_id'];$to=$this->postJson('/api/v1/warehouses',['name'=>'Secondary Warehouse'],$h)->assertCreated()->json('_id');$this->postJson('/api/v1/inventory/adjustments',['productId'=>(int)$product,'warehouseId'=>(int)$from,'type'=>'add','quantity'=>50,'reason'=>'Opening balance'],$h)->assertCreated()->assertJsonPath('balance',50);$this->postJson('/api/v1/inventory/adjustments',['productId'=>(int)$product,'warehouseId'=>(int)$from,'type'=>'remove','quantity'=>10,'reason'=>'Damaged'],$h)->assertCreated()->assertJsonPath('balance',40);$this->postJson('/api/v1/inventory/transfers',['productId'=>(int)$product,'fromWarehouseId'=>(int)$from,'toWarehouseId'=>(int)$to,'quantity'=>15,'reason'=>'Replenishment'],$h)->assertCreated()->assertJsonPath('transferred',15);$this->postJson('/api/v1/inventory/adjustments',['productId'=>(int)$product,'warehouseId'=>(int)$from,'type'=>'remove','quantity'=>30],$h)->assertStatus(422);$this->assertDatabaseHas('stock_balances',['product_id'=>$product,'warehouse_id'=>$from,'quantity'=>25]);$this->assertDatabaseHas('stock_balances',['product_id'=>$product,'warehouse_id'=>$to,'quantity'=>15]);$this->getJson('/api/v1/products',$h)->assertOk()->assertJsonPath('0.totalStock',40);$this->getJson('/api/v1/inventory/adjustments',$h)->assertOk()->assertJsonCount(3);$this->getJson('/api/v1/inventory/valuation',$h)->assertOk()->assertJsonPath('totalUnits',40)->assertJsonPath('totalCostValue',400)->assertJsonPath('totalSellValue',600)->assertJsonPath('potentialProfit',200)->assertJsonStructure(['categoryBreakdown']);}}
